// Numeric statistics helpers. Input arrays must contain finite numbers.
fn mean(values) { "Return the arithmetic mean of a non-empty numeric array."; if (len(values) == 0) { throw "mean: array is empty"; } let total = 0; let i = 0; while (i < len(values)) { total += values[i]; i++; } return total / len(values); }
fn min(values) { "Return the smallest value in a non-empty numeric array."; if (len(values) == 0) { throw "min: array is empty"; } let result = values[0]; let i = 1; while (i < len(values)) { if (values[i] < result) { result = values[i]; } i++; } return result; }
fn max(values) { "Return the largest value in a non-empty numeric array."; if (len(values) == 0) { throw "max: array is empty"; } let result = values[0]; let i = 1; while (i < len(values)) { if (values[i] > result) { result = values[i]; } i++; } return result; }
fn variance(values) { "Return population variance (divide by N) of a non-empty numeric array."; let average = mean(values); let total = 0; let i = 0; while (i < len(values)) { total += (values[i] - average) * (values[i] - average); i++; } return total / len(values); }
fn standard_deviation(values) { "Return population standard deviation of a non-empty numeric array."; return sqrt(variance(values)); }
fn median(values) { "Return the median of a non-empty numeric array without modifying input."; if (len(values) == 0) { throw "median: array is empty"; } let sorted = []; let i = 0; while (i < len(values)) { push(sorted, values[i]); i++; } i = 1; while (i < len(sorted)) { let current = sorted[i]; let j = i - 1; while (j >= 0 && sorted[j] > current) { sorted[j + 1] = sorted[j]; j--; } sorted[j + 1] = current; i++; } let middle = floor(len(sorted) / 2); if (len(sorted) % 2 == 1) { return sorted[middle]; } return (sorted[middle - 1] + sorted[middle]) / 2; }
